test('adjustStock running alongside reserve, commit and release loses no updates', async () => {
  const svc = await service({ widget: 100 });
  const ops = [];
  for (let i = 0; i < 20; i++) {
    ops.push(svc.reserve(`o${i}`, [{ sku: 'widget', qty: 2 }]).then(() => svc.commit(`o${i}`)));
    ops.push(svc.reserve(`r${i}`, [{ sku: 'widget', qty: 1 }]).then(() => svc.release(`r${i}`)));
    ops.push(svc.adjustStock('widget', 3, 'count'));
    ops.push(svc.adjustStock('widget', -1, 'count'));
    await new Promise(resolve => setImmediate(resolve));
  }
  await Promise.all(ops);
